from pathlib import Path
import subprocess,json,hashlib
L=Path(__file__).resolve().parent;R=L.parents[1];m=json.loads((L/'runtime.json').read_text());source=m['server_source_expected'];paths=subprocess.check_output(['git','ls-tree','-r','--name-only',source,'--','services/server/video_viewer','services/server/migrations','services/server/alembic.ini','services/server/requirements.lock'],text=True,cwd=R).splitlines();expected={p.removeprefix('services/server/'):hashlib.sha256(subprocess.check_output(['git','show',source+':'+p],cwd=R)).hexdigest() for p in paths}
code="import pathlib,json,hashlib; names=json.loads(input());print(json.dumps({p:hashlib.sha256((pathlib.Path('/app')/p).read_bytes()).hexdigest() for p in names}))";raw=subprocess.check_output(['docker','exec','-i',m['id'],'python','-c',code],input=json.dumps(list(expected)).encode());actual=json.loads(raw);assert expected==actual;(L/'old-server-source.json').write_text(json.dumps({'source':source,'actual_image':m['image'],'files':actual,'all_files_equal':True},indent=2)+'\n');print({'old_source_matches_git_files':len(actual),'source':source})
